        int maxContacts;
    };

    // cpSpaceArbiterIteratorFunc: converts one cached cpArbiter into a
    // ContactInfo entry (subject to filtering and the contact cap).
    void collectArbiterContacts(cpArbiter* arb, void* data)
    {
        ArbiterQueryContext* context = static_cast<ArbiterQueryContext*>(data);
        if (static_cast<int>(context->contacts->size()) >= context->maxContacts)
        {
            return;
        }

        cpShape* cpShapeA = nullptr;
        cpShape* cpShapeB = nullptr;
        cpArbiterGetShapes(arb, &cpShapeA, &cpShapeB);

        PhysicsShape* shapeA = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeA));
        PhysicsShape* shapeB = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeB));
        if (shapeA == nullptr || shapeB == nullptr)
        {
            return;
        }

        if (!context->manager->filterContact(shapeA, shapeB))
        {
            return;
        }

        ContactInfo info;
        info.shapeA = shapeA;
        info.shapeB = shapeB;
        info.normal = PhysicsHelper::cpv2point(cpArbiterGetNormal(arb));

        int count = cpArbiterGetCount(arb);
        if (count > MAX_CONTACT_POINTS)
        {
            count = MAX_CONTACT_POINTS;
        }
        info.pointCount = count;
        for (int i = 0; i < count; ++i)
        {
            info.contactPoints[i] = PhysicsHelper::cpv2point(cpArbiterGetPointA(arb, i));
            info.depths[i] = PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arb, i));
        }
        for (int i = count; i < MAX_CONTACT_POINTS; ++i)
        {
            info.contactPoints[i] = Vec2::ZERO;
            info.depths[i] = 0.0f;
        }

        cpVect impulse = cpArbiterTotalImpulse(arb);
        info.totalImpulse = PhysicsHelper::cpfloat2float(cpvlength(impulse));
        info.isNew = cpArbiterIsFirstContact(arb) != cpFalse;
        info.isPersistent = !info.isNew;

        if (context->customFilter != nullptr && *context->customFilter && !(*context->customFilter)(info))
        {
            return;
        }

        context->contacts->push_back(info);
    }
}

PhysicsContactManager::PhysicsContactManager()
: _world(nullptr)
, _maxContacts(256)
, _initialized(false)
{
}

PhysicsContactManager::~PhysicsContactManager()
{
}

bool PhysicsContactManager::init(PhysicsWorld* world, int maxContacts)
{
    if (world == nullptr || maxContacts <= 0)
    {
        return false;
    }

    _world = world;
    _maxContacts = maxContacts;

    _contacts.clear();
    _contacts.reserve(_maxContacts);
    _beginCallbacks.clear();
    _preSolveCallbacks.clear();
    _postSolveCallbacks.clear();
    _separateCallbacks.clear();
    _customFilter = nullptr;

    _initialized = true;
    return true;
}

void PhysicsContactManager::clear()
{
    _contacts.clear();
    _beginCallbacks.clear();
    _preSolveCallbacks.clear();
    _postSolveCallbacks.clear();
    _separateCallbacks.clear();
    _customFilter = nullptr;
}

void PhysicsContactManager::processContacts(cpSpace* space)
{
    if (space == nullptr)
    {
        return;
    }

    // Keep last step's contacts so separated pairs can be detected below.
    std::vector<ContactInfo> previousContacts;
    previousContacts.swap(_contacts);
    _contacts.reserve(_maxContacts);

    ArbiterQueryContext context;
    context.manager = this;
    context.contacts = &_contacts;
    context.customFilter = &_customFilter;
    context.maxContacts = _maxContacts;
    cpSpaceEachArbiter(space, &collectArbiterContacts, &context);

    // Dispatch begin/preSolve/postSolve for the freshly collected contacts.
    for (const auto& info : _contacts)
    {
        if (info.isNew)
        {
            dispatchBeginEvent(info);
        }
        dispatchPreSolveEvent(info);
        dispatchPostSolveEvent(info);
    }

    // Any pair that was touching last step but is gone now has separated.
    for (const auto& old : previousContacts)
    {
        bool stillActive = false;
        for (const auto& info : _contacts)
        {
            if ((info.shapeA == old.shapeA && info.shapeB == old.shapeB)
                || (info.shapeA == old.shapeB && info.shapeB == old.shapeA))
            {
                stillActive = true;
                break;
            }
        }

        if (!stillActive)
        {
            dispatchSeparateEvent(old);
        }
    }
}

bool PhysicsContactManager::filterContact(PhysicsShape* shapeA, PhysicsShape* shapeB) const
{
    if (shapeA == nullptr || shapeB == nullptr)
    {
        return false;
    }

    // Chipmunk group semantics: shapes sharing a non-zero group always
    // collide (positive group) or never collide (negative group).
    int groupA = shapeA->getGroup();
    int groupB = shapeB->getGroup();
    if (groupA != 0 && groupA == groupB)
    {
        return groupA > 0;
    }

    // Contact test bitmask: both shapes must be interested in the other.
    if ((shapeA->getCategoryBitmask() & shapeB->getContactTestBitmask()) == 0
        || (shapeB->getCategoryBitmask() & shapeA->getContactTestBitmask()) == 0)
    {
        return false;
    }

    // Collision bitmask: both shapes must be allowed to collide.
    if ((shapeA->getCategoryBitmask() & shapeB->getCollisionBitmask()) == 0
        || (shapeB->getCategoryBitmask() & shapeA->getCollisionBitmask()) == 0)
    {
        return false;
    }

    return true;
}

void PhysicsContactManager::addBeginCallback(ContactCallbackFunc callback)
{
    if (callback)
    {
        _beginCallbacks.push_back(callback);
    }
}

void PhysicsContactManager::addPreSolveCallback(ContactCallbackFunc callback)
{
