    {
        _preSolveCallbacks.push_back(callback);
    }
}

void PhysicsContactManager::addPostSolveCallback(ContactCallbackFunc callback)
{
    if (callback)
    {
        _postSolveCallbacks.push_back(callback);
    }
}

void PhysicsContactManager::addSeparateCallback(ContactCallbackFunc callback)
{
    if (callback)
    {
        _separateCallbacks.push_back(callback);
    }
}

void PhysicsContactManager::setContactFilter(ContactFilterFunc filter)
{
    _customFilter = filter;
}

int PhysicsContactManager::getContactCount() const
{
    return static_cast<int>(_contacts.size());
}

int PhysicsContactManager::getActiveContactCount() const
{
    int count = 0;
    for (const auto& info : _contacts)
    {
        if (info.pointCount > 0)
        {
            ++count;
        }
    }
    return count;
}

const ContactInfo* PhysicsContactManager::getContact(int index) const
{
    if (index < 0 || index >= static_cast<int>(_contacts.size()))
    {
        return nullptr;
    }
    return &_contacts[index];
}

const ContactInfo* PhysicsContactManager::findContactBetween(PhysicsBody* bodyA, PhysicsBody* bodyB) const
{
    if (bodyA == nullptr || bodyB == nullptr)
    {
        return nullptr;
    }

    for (const auto& info : _contacts)
    {
        PhysicsBody* contactBodyA = info.shapeA != nullptr ? info.shapeA->getBody() : nullptr;
        PhysicsBody* contactBodyB = info.shapeB != nullptr ? info.shapeB->getBody() : nullptr;
        if ((contactBodyA == bodyA && contactBodyB == bodyB)
            || (contactBodyA == bodyB && contactBodyB == bodyA))
        {
            return &info;
        }
    }
    return nullptr;
}

bool PhysicsContactManager::isContactActive(PhysicsShape* shapeA, PhysicsShape* shapeB) const
{
    if (shapeA == nullptr || shapeB == nullptr)
    {
        return false;
    }

    for (const auto& info : _contacts)
    {
        if ((info.shapeA == shapeA && info.shapeB == shapeB)
            || (info.shapeA == shapeB && info.shapeB == shapeA))
        {
            return true;
        }
    }
    return false;
}

Vec2 PhysicsContactManager::getContactNormal(int index) const
{
    const ContactInfo* info = getContact(index);
    return info != nullptr ? info->normal : Vec2::ZERO;
}

float PhysicsContactManager::getContactDepth(int index) const
{
    const ContactInfo* info = getContact(index);
    if (info == nullptr || info->pointCount <= 0)
    {
        return 0.0f;
    }

    // Report the deepest penetration among the contact's points.
    float depth = info->depths[0];
    for (int i = 1; i < info->pointCount; ++i)
    {
        if (info->depths[i] > depth)
        {
            depth = info->depths[i];
        }
    }
    return depth;
}

float PhysicsContactManager::getTotalImpulse(int index) const
{
    const ContactInfo* info = getContact(index);
    return info != nullptr ? info->totalImpulse : 0.0f;
}

void PhysicsContactManager::setMaxContacts(int max)
{
    if (max <= 0)
    {
        return;
    }

    _maxContacts = max;
    if (static_cast<int>(_contacts.size()) > _maxContacts)
    {
        _contacts.resize(_maxContacts);
    }
}

int PhysicsContactManager::getMaxContacts() const
{
    return _maxContacts;
}

void PhysicsContactManager::dispatchBeginEvent(const ContactInfo& info)
{
    for (const auto& callback : _beginCallbacks)
    {
        callback(info);
    }
}

void PhysicsContactManager::dispatchPreSolveEvent(const ContactInfo& info)
{
    for (const auto& callback : _preSolveCallbacks)
    {
        callback(info);
    }
}

void PhysicsContactManager::dispatchPostSolveEvent(const ContactInfo& info)
{
    for (const auto& callback : _postSolveCallbacks)
    {
        callback(info);
    }
}

void PhysicsContactManager::dispatchSeparateEvent(const ContactInfo& info)
{
    for (const auto& callback : _separateCallbacks)
    {
        callback(info);
    }
}

